import java.io.*;
import java.util.*;

public class Main {
    static class FastIO {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");
        String read() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int readInt() {
            return Integer.parseInt(read());
        }
        long readLong() {
            return Long.parseLong(read());
        }
    }

    public static void main(String[] args) {
        FastIO io = new FastIO();
        PrintWriter out = new PrintWriter(System.out);
        int T = 1;
        for (int t=0; t<T; t++) {
            Computation comp = new Computation(out, io);
            comp.execute(T, t);
        }
        out.flush();
    }
}

class Computation {
    PrintWriter out;
    FastIO io;

    public Computation(PrintWriter out, FastIO io) {
        this.out=out;
        this.io=io;
    }

    public void execute(int all, int t) {
        int n=io.readInt();
        int mod=io.readInt();

        long[][] dp=new long[n][n*n+5];
        dp[0][0]=1;
        for(int i=1;i<n;i++){
            for(int j=0;j<dp[0].length;j++){
                for(int c=0;c<=i;c++){
                    if(j-c>=0){
                        dp[i][j]+=dp[i-1][j-c];
                        dp[i][j]%=mod;
                        if(dp[i][j]==0)dp[i][j]+=mod;
                    }
                }
            }
        }

        long[][] prefixSum=new long[dp.length][dp[0].length];
        for(int i=0;i<dp.length;i++){
            long sum=0;
            for(int j=0;j<dp[0].length;j++){
                sum+=dp[i][j];
                sum%=mod;
                if(sum==0)sum+=mod;
                prefixSum[i][j]=sum;
            }
        }

        long[] factorial=new long[501*501];
        factorial[0]=1;
        for(int i=1;i<factorial.length;i++){
            factorial[i]=(factorial[i-1]*i)%mod;
        }

        long[][] nCr=new long[501][501];
        nCr[0][0]=1;
        for(int i=1;i<=500;i++){
            nCr[i][0]=1;
            for(int j=1;j<=i;j++){
                nCr[i][j]=(nCr[i-1][j]+nCr[i-1][j-1])%mod;
            }
        }

        long answer=0;
        for(int i=0;i<=n-2;i++){
            int cnt=n-i;
            int pre=n-cnt;
            long comb=(nCr[n][pre]*factorial[pre])%mod;
            long total=0;
            long[] last=dp[cnt-2];
            long ssum=0;
            long totalSum=0;
            for(int j=2;j<dp[0].length;j++){
                total+=prefixSum[cnt-2][j-2]*(cnt-1);
                total%=mod;

                long val=last[j]*total;
                answer+=val;
                answer%=mod;

                ssum+=prefixSum[cnt-2][j-2];
                if(j-cnt-1>=0)ssum-=prefixSum[cnt-2][j-cnt-1];
                ssum=(ssum+mod)%mod;

                total-=ssum;
                total=(total+mod)%mod;
            }
            answer+=(prefixSum[cnt-2][0]*comb)%mod;
            answer%=mod;
        }
        out.println(answer);
    }
}
